     4	import { after, type NextRequest, NextResponse } from "next/server";
     5	import { env } from "@/env";
     6	
     7	/**
     8	 * The one-click unsubscribe the privacy policy promises. The token is the
     9	 * durable per-subscriber capability minted at confirmation; acting on it
    10	 * deletes the subscriber document — a deletion, not a flag — and removes
    11	 * the contact from the Resend audience, so neither store keeps the
    12	 * address. Digest broadcasts must link this endpoint rather than Resend's
    13	 * hosted unsubscribe, which only marks the contact suppressed and would
    14	 * leave our database holding an address the policy says is gone.
    15	 */
    16	export async function GET(request: NextRequest) {
    17	  try {
    18	    const { searchParams } = new URL(request.url);
    19	    const token = searchParams.get("token");
    20	
    21	    if (!token) {
    22	      return NextResponse.json(
    23	        { error: "A valid unsubscribe link is required" },
    24	        { status: 400 }
    25	      );
    26	    }
    27	
    28	    const subscriber = await database.subscriber.findOne({
    29	      unsubscribeToken: token,
    30	    });
    31	
    32	    if (!subscriber) {
    33	      return NextResponse.json(
    34	        { error: "Invalid unsubscribe link" },
    35	        { status: 400 }
    36	      );
    37	    }
    38	
    39	    // The audience removal is tolerated failing (the contact may already be
    40	    // gone); the database deletion is not — it is the promise.
    41	    const removeContact = resend.contacts
    42	      .remove({ audienceId: env.RESEND_AUDIENCE_ID, email: subscriber.email })
    43	      .then(({ error }) => {
    44	        if (error) {
    45	          after(() => parseError(error));
    46	        }
    47	      });
    48	
    49	    await Promise.all([
    50	      database.subscriber.deleteOne({ _id: subscriber._id }),
    51	      removeContact,
    52	    ]);
    53	
    54	    return new Response(null, {
    55	      headers: {
    56	        Location: "/unsubscribed",
    57	      },
    58	      status: 303,
    59	    });
    60	  } catch (error) {
    61	    after(() => parseError(error));
    62	    return NextResponse.json(
    63	      { error: "An unexpected error occurred" },
    64	      { status: 500 }
    65	    );
    66	  }
